import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_OW": 64, "BLOCK_N": 64, "BLOCK_K": 16, "grf_mode": "256"},
            num_warps=4,
            num_stages=3,
        ),
    ],
    key=["D", "H", "W", "C_IN", "C_OUT", "OD", "OH", "OW"],
)
@triton.jit
def _conv3d_spatial_tiled(
    x_ptr,
    w_ptr,
    y_ptr,
    N_batch,
    D,
    H,
    W,
    OD,
    OH,
    OW,
    sx_n,
    sx_d,
    sx_h,
    sw_kd,
    sw_kh,
    sw_kw,
    sw_ci,
    sw_co,
    sy_n,
    sy_d,
    sy_h,
    BLOCK_OW: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    KD: tl.constexpr,
    KH: tl.constexpr,
    KW: tl.constexpr,
    PAD: tl.constexpr,
    C_IN: tl.constexpr,
    C_OUT: tl.constexpr,
    grf_mode: tl.constexpr,
):
    n = tl.program_id(0)
    pid_dh = tl.program_id(1)
    pid_wn = tl.program_id(2)

    od = pid_dh // OH
    oh = pid_dh % OH

    num_ow_tiles = tl.cdiv(OW, BLOCK_OW)
    pid_ow = pid_wn % num_ow_tiles
    pid_n = pid_wn // num_ow_tiles
    ow0 = pid_ow * BLOCK_OW

    acc = tl.zeros((BLOCK_OW, BLOCK_N), dtype=tl.float32)

    x_n_base = x_ptr + n.to(tl.int64) * sx_n

    for kd in range(KD):
        d_in = od + kd - PAD
        d_ok = (d_in >= 0) & (d_in < D)
        if d_ok:
            for kh in range(KH):
                h_in = oh + kh - PAD
                h_ok = (h_in >= 0) & (h_in < H)
                if h_ok:
                    x_dh_base = x_n_base + d_in * sx_d + h_in * sx_h

                    for kw in range(KW):
                        w_start = ow0 + kw - PAD

                        x_bp = tl.make_block_ptr(
                            base=x_dh_base,
                            shape=(W, C_IN),
                            strides=(C_IN, 1),
                            offsets=(w_start, 0),
                            block_shape=(BLOCK_OW, BLOCK_K),
                            order=(1, 0),
                        )

                        w_bp = tl.make_block_ptr(
                            base=w_ptr + kd * sw_kd + kh * sw_kh + kw * sw_kw,
                            shape=(C_IN, C_OUT),
                            strides=(sw_ci, sw_co),
                            offsets=(0, pid_n * BLOCK_N),
                            block_shape=(BLOCK_K, BLOCK_N),
                            order=(1, 0),
                        )

                        for c0 in range(0, C_IN, BLOCK_K):
                            x_tile = tl.load(
                                x_bp, boundary_check=(0, 1), padding_option="zero"
                            )
                            w_tile = tl.load(
                                w_bp, boundary_check=(0, 1), padding_option="zero"
                            )
                            acc = tl.dot(x_tile, w_tile, acc)
                            x_bp = tl.advance(x_bp, (0, BLOCK_K))
                            w_bp = tl.advance(w_bp, (BLOCK_K, 0))

    y_dh_base = y_ptr + n.to(tl.int64) * sy_n + od * sy_d + oh * sy_h
    y_valid = OW - ow0
    y_bp = tl.make_block_ptr(
        base=y_dh_base,
        shape=(y_valid, C_OUT),
        strides=(C_OUT, 1),
        offsets=(0, pid_n * BLOCK_N),
        block_shape=(BLOCK_OW, BLOCK_N),
        order=(1, 0),
    )
    tl.store(y_bp, acc.to(tl.float16), boundary_check=(0, 1))


class Model(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        groups: int = 1,
        bias: bool = False,
    ):
        super(Model, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )
        self._packed = False
        self._ks = kernel_size
        self._pad = padding

    def _pack_weights(self):
        w = self.conv_transpose3d.weight.data
        self._w_dhwio = (
            w.flip(2, 3, 4).permute(2, 3, 4, 0, 1).to(dtype=torch.float16).contiguous()
        )
        self._packed = True

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not self._packed:
            self._pack_weights()
        if x.dtype != torch.float16:
            x = x.to(dtype=torch.float16)

        x = x.to(memory_format=torch.channels_last_3d)
        x_ndhwc = x.permute(0, 2, 3, 4, 1)

        N_b, C_in, D, H, W = x.shape
        C_out = self._w_dhwio.shape[4]
        KS = self._ks
        PAD = KS - 1 - self._pad

        OD = D + 2 * PAD - KS + 1
        OH = H + 2 * PAD - KS + 1
        OW = W + 2 * PAD - KS + 1

        conv_out = torch.empty(
            (N_b, C_out, OD, OH, OW),
            device=x.device,
            dtype=torch.float16,
            memory_format=torch.channels_last_3d,
        )
        conv_ndhwc = conv_out.permute(0, 2, 3, 4, 1)

        def conv_grid(meta):
            return (
                N_b,
                OD * OH,
                triton.cdiv(OW, meta["BLOCK_OW"]) * triton.cdiv(C_out, meta["BLOCK_N"]),
            )

        _conv3d_spatial_tiled[conv_grid](
            x_ndhwc,
            self._w_dhwio,
            conv_ndhwc,
            N_b,
            D,
            H,
            W,
            OD,
            OH,
            OW,
            x_ndhwc.stride(0),
            x_ndhwc.stride(1),
            x_ndhwc.stride(2),
            self._w_dhwio.stride(0),
            self._w_dhwio.stride(1),
            self._w_dhwio.stride(2),
            self._w_dhwio.stride(3),
            self._w_dhwio.stride(4),
            conv_ndhwc.stride(0),
            conv_ndhwc.stride(1),
            conv_ndhwc.stride(2),
            KD=KS,
            KH=KS,
            KW=KS,
            PAD=PAD,
            C_IN=C_in,
            C_OUT=C_out,
        )

        return conv_out


